<?php require_once __DIR__.'/../funciones.php'; exigir_admin();if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$estado=$_POST['estado']??'Pendiente';$validos=['Pendiente','En preparación','En camino','Entregado','Cancelado'];if(in_array($estado,$validos,true)){$q=$conn->prepare('UPDATE pedidos SET estado=? WHERE id=?');$q->bind_param('si',$estado,$id);$q->execute();aviso('Estado del pedido actualizado.');}header('Location: pedidos.php');exit;}$rs=$conn->query('SELECT p.*,u.nombre cliente,u.usuario,mp.nombre pago,me.nombre envio FROM pedidos p JOIN usuarios u ON u.id=p.usuario_id JOIN metodos_pago mp ON mp.id=p.metodo_pago_id JOIN metodos_envio me ON me.id=p.metodo_envio_id ORDER BY p.creado_en DESC');?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos</title><link rel="stylesheet" href="../estilos.css"></head><body><?php include 'menu.php';?><main class="contenedor"><h1 class="titulo">Pedidos de clientes</h1><?php mostrar_aviso();?><div class="panel tabla-wrap"><table><tr><th>N.º / Fecha</th><th>Cliente</th><th>Detalle</th><th>Total</th><th>Envío / Pago</th><th>Estado</th><th>Actualizar</th></tr><?php while($p=$rs->fetch_assoc()):?><tr><td>#<?=$p['id']?><br><small><?=e($p['creado_en'])?></small></td><td><?=e($p['cliente'])?><br><small><?=e($p['usuario'])?></small></td><td><?php $idp=(int)$p['id'];$d=$conn->query("SELECT nombre_producto,cantidad FROM pedido_detalles WHERE pedido_id=$idp");while($x=$d->fetch_assoc())echo e($x['cantidad'].' x '.$x['nombre_producto']).'<br>';?></td><td>S/ <?=number_format($p['total'],2)?></td><td><?=e($p['envio'])?><br><?=e($p['pago'])?><br><small><?=e($p['direccion'])?></small></td><td><span class="etiqueta"><?=e($p['estado'])?></span></td><td><form method="post"><input type="hidden" name="id" value="<?=$p['id']?>"><select name="estado"><?php foreach(['Pendiente','En preparación','En camino','Entregado','Cancelado'] as $s):?><option <?=$s===$p['estado']?'selected':''?>><?=e($s)?></option><?php endforeach;?></select><button class="btn" style="margin-top:6px">Guardar</button></form></td></tr><?php endwhile;?></table></div></main></body></html>
